  { slug: 'tongji',   name: '同济大学',       url: 'https://www.tongji.edu.cn/' },
  { slug: 'seu',      name: '东南大学',       url: 'https://www.seu.edu.cn/' },
  { slug: 'xjtu',     name: '西安交通大学',   url: 'https://www.xjtu.edu.cn/' },
  { slug: 'nankai',   name: '南开大学',       url: 'https://www.nankai.edu.cn/' },
  { slug: 'sysu',     name: '中山大学',       url: 'https://www.sysu.edu.cn/' },
  { slug: 'scut',     name: '华南理工大学',   url: 'https://www.scut.edu.cn/' },
  { slug: 'hit',      name: '哈尔滨工业大学', url: 'https://www.hit.edu.cn/' },
  { slug: 'cqu',      name: '重庆大学',       url: 'https://www.cqu.edu.cn/' },
  { slug: 'uestc',    name: '电子科技大学',   url: 'https://www.uestc.edu.cn/' },
];

const results = [];

for (let i = 0; i < targets.length; i++) {
  const t = targets[i];
  const started = Date.now();
  const rec = { slug: t.slug, name: t.name, url: t.url, ran_at: new Date().toISOString() };
  let page;
  try {
    page = await browser.newPage();
    await page.goto(t.url, { waitUntil: 'domcontentloaded', timeout: 40000 });
    await page.waitForTimeout(3000);

    let d = await page.evaluate(() => {
      const b = document.body;
      const text = b ? (b.innerText || '').replace(/\s+/g, ' ').trim() : '';
      return {
        title: document.title || '',
        textLen: text.length,
        linkCount: document.querySelectorAll('a[href]').length,
        imgCount: document.querySelectorAll('img').length,
        hasRoot: !!document.querySelector('#root, #app'),
        head: text.slice(0, 120),
      };
    });

    if (d.textLen < 200) {
      await page.waitForTimeout(3500);
      const r2 = await page.evaluate(() => {
        const b = document.body;
        const text = b ? (b.innerText || '').replace(/\s+/g, ' ').trim() : '';
        return { textLen: text.length, linkCount: document.querySelectorAll('a[href]').length, head: text.slice(0, 120) };
      });
      if (r2.textLen > d.textLen) {
        d.textLen = r2.textLen;
        d.linkCount = r2.linkCount;
        d.head = r2.head;
        d.retried = true;
      }
    }

    rec.ok = true;
    rec.elapsed_ms = Date.now() - started;
    Object.assign(rec, d);
  } catch (e) {
    rec.ok = false;
    rec.elapsed_ms = Date.now() - started;
    rec.error = String((e && e.message) || e).slice(0, 200);
  }
  results.push(rec);
  console.info('CB ' + JSON.stringify({ i: i + 1, slug: rec.slug, ok: rec.ok, len: rec.textLen || 0, links: rec.linkCount || 0 }));
}

console.info('CB_ALL ' + JSON.stringify(results));
console.info('ALL DONE');

